CREATE TABLE tenants (id text PRIMARY KEY, name text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE users (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('operator','technician','owner','responder')), house_ids text[], active boolean NOT NULL DEFAULT true);
CREATE TABLE houses (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, name text NOT NULL, address text NOT NULL, lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90), lng double precision NOT NULL CHECK(lng BETWEEN -180 AND 180), timezone text NOT NULL DEFAULT 'America/Los_Angeles', status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','MAINTENANCE','ARCHIVED')), version int NOT NULL DEFAULT 1, UNIQUE(tenant_id,name), UNIQUE(id,tenant_id));
CREATE TABLE rooms (id text PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, name text NOT NULL, room_type text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')), version int NOT NULL DEFAULT 1, FOREIGN KEY(house_id,tenant_id) REFERENCES houses(id,tenant_id), UNIQUE(house_id,name), UNIQUE(id,house_id,tenant_id));
CREATE TABLE devices (id text PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, room_id text NOT NULL, name text NOT NULL, type text NOT NULL CHECK(type IN ('camera','microphone','sensor','appliance','gateway')), serial_no text NOT NULL, capabilities jsonb NOT NULL DEFAULT '[]', firmware_version text, status text NOT NULL DEFAULT 'REGISTERED' CHECK(status IN ('REGISTERED','PROVISIONING','ONLINE','OFFLINE','MAINTENANCE','ARCHIVED')), last_seen timestamptz, config jsonb NOT NULL DEFAULT '{}', config_version int NOT NULL DEFAULT 0, reported_version int NOT NULL DEFAULT 0, version int NOT NULL DEFAULT 1, credential_hash text, FOREIGN KEY(room_id,house_id,tenant_id) REFERENCES rooms(id,house_id,tenant_id), UNIQUE(tenant_id,serial_no), UNIQUE(id,house_id,tenant_id));
CREATE TABLE configurations (device_id text REFERENCES devices, version int, config jsonb NOT NULL, actor text NOT NULL, created_at timestamptz DEFAULT now(), applied_at timestamptz, PRIMARY KEY(device_id,version));
CREATE TABLE commands (id text PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, device_id text NOT NULL, command text NOT NULL, parameters jsonb NOT NULL, state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','SENT','ACKED','FAILED','EXPIRED')), idempotency_key text NOT NULL, fingerprint text NOT NULL, correlation_id text NOT NULL, created_at timestamptz DEFAULT now(), FOREIGN KEY(device_id,house_id,tenant_id) REFERENCES devices(id,house_id,tenant_id), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE events (id text NOT NULL, tenant_id text NOT NULL, house_id text NOT NULL, device_id text NOT NULL, type text NOT NULL, occurred_at timestamptz NOT NULL, source text NOT NULL, confidence double precision CHECK(confidence BETWEEN 0 AND 1), correlation_id text NOT NULL, fingerprint text NOT NULL, idempotency_key text NOT NULL, envelope jsonb, processing_state text NOT NULL DEFAULT 'PENDING' CHECK(processing_state IN ('PENDING','CONSISTENT','QUARANTINED')), attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,idempotency_key), FOREIGN KEY(device_id,house_id,tenant_id) REFERENCES devices(id,house_id,tenant_id));
CREATE INDEX event_history ON events(tenant_id,house_id,occurred_at DESC,id);
CREATE TABLE alerts (id text PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, device_id text NOT NULL, event_id text NOT NULL, type text NOT NULL, severity text NOT NULL CHECK(severity IN ('CRITICAL','HIGH','MEDIUM','INFO')), state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','ACKNOWLEDGED','INVESTIGATING','ESCALATED','RESOLVED')), assigned_to text REFERENCES users, version int NOT NULL DEFAULT 1, evidence_count int NOT NULL DEFAULT 1, explanation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,event_id) REFERENCES events(tenant_id,id), FOREIGN KEY(device_id,house_id,tenant_id) REFERENCES devices(id,house_id,tenant_id));
CREATE TABLE alert_evidence (alert_id text REFERENCES alerts, tenant_id text, event_id text, PRIMARY KEY(tenant_id,event_id), FOREIGN KEY(tenant_id,event_id) REFERENCES events(tenant_id,id));
CREATE TABLE audit_log (id bigserial PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, house_id text, actor text NOT NULL, action text NOT NULL, target text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE live_events (id bigserial PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, type text NOT NULL, payload jsonb NOT NULL, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX live_scope ON live_events(tenant_id,id);
CREATE TABLE notifications (id text PRIMARY KEY, tenant_id text NOT NULL, house_id text NOT NULL, alert_id text NOT NULL REFERENCES alerts, channel text NOT NULL DEFAULT 'SIMULATED', recipient text NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','FAILED','EXHAUSTED')), attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz DEFAULT now(), last_error text, created_at timestamptz DEFAULT now());
CREATE TABLE preferences (user_id text PRIMARY KEY REFERENCES users, settings jsonb NOT NULL);
